-- Hama Work notification diagnostic - read-only checks.
-- Run in Supabase SQL Editor. This does not change data.

-- 1) Recent notifications generated by the database.
SELECT id, user_id, type, title, created_at
FROM public.notifications
ORDER BY created_at DESC
LIMIT 30;

-- 2) Active push subscriptions by user/device.
SELECT
  user_id,
  platform,
  active,
  endpoint,
  last_seen_at,
  updated_at
FROM public.user_push_subscriptions
ORDER BY last_seen_at DESC
LIMIT 100;

-- 3) Realtime publication contains notifications.
SELECT pubname, schemaname, tablename
FROM pg_publication_tables
WHERE pubname = 'supabase_realtime'
  AND schemaname = 'public'
  AND tablename = 'notifications';

-- 4) Database triggers on notifications.
SELECT
  tgname,
  tgenabled,
  pg_get_triggerdef(oid) AS trigger_definition
FROM pg_trigger
WHERE tgrelid = 'public.notifications'::regclass
  AND NOT tgisinternal
ORDER BY tgname;
